    /// The app's events from log index `from`, then live, until the stream is cancelled.
    public func events(from: Int = 0) -> AsyncThrowingStream<EventFrame, Error> {
        guard case .client(let client, let app) = transport else {
            return AsyncThrowingStream { $0.finish(throwing: MeroAppBackendUnsupported(method: "events")) }
        }
        let upstream = client.events(app, from: from)
        return AsyncThrowingStream { continuation in
            let task = Task {
                do {
                    for try await event in upstream {
                        continuation.yield(EventFrame(id: event.id, event: try Event(kind: event.kind, data: event.data)))
                    }
                    continuation.finish()
                } catch {
                    continuation.finish(throwing: error)
                }
            }
            continuation.onTermination = { _ in task.cancel() }
        }
    }

    private func invokeCall<Wire: Decodable>(
        _ method: String, _ args: Args, idempotencyKey: String?, as type: Wire.Type
    ) async throws -> Wire {
        let argsJSON = try Self.json(args)
        switch transport {
        case .client(let client, let app):
            let answer = try await client.callJSON(app, method, argsJSON: argsJSON, idempotencyKey: idempotencyKey)
            return try Self.result(Wire.self, of: answer)
        case .contract(let contract):
            guard idempotencyKey == nil else { throw MeroAppBackendUnsupported(method: method) }
            return try JSONDecoder().decode(Wire.self, from: try await contract.execute(method: method, argsJSON: argsJSON))
        }
    }

    private func invokeView<Wire: Decodable>(
        _ method: String, _ args: Args, stale: Bool, minIndex: Int, as type: Wire.Type
    ) async throws -> Wire {
        let argsJSON = try Self.json(args)
        switch transport {
        case .client(let client, let app):
            let answer = try await client.viewJSON(app, method, argsJSON: argsJSON, stale: stale, minIndex: minIndex)
            return try Self.result(Wire.self, of: answer)
        case .contract(let contract):
            return try JSONDecoder().decode(Wire.self, from: try await contract.query(method: method, argsJSON: argsJSON))
        }
    }

    private func invokeConfirmed<Wire: Decodable>(
        _ method: String, _ args: Args, passkey: any PasskeyProvider, idempotencyKey: String?, as type: Wire.Type
    ) async throws -> Wire {
        guard case .client(let client, let app) = transport else {
            throw MeroAppBackendUnsupported(method: method)
        }
        let value = try JSONDecoder().decode(JSONValue.self, from: Self.json(args))
        let answer = try await client.callConfirmed(app, method, value, passkey: passkey, idempotencyKey: idempotencyKey)
        return try JSONDecoder().decode(Wire.self, from: JSONEncoder().encode(answer.result ?? .null))
    }

    /// An event of the app, as `events` and `MeroAppBackend.events` carry it.
    public enum Event: Sendable {
        /// The event `AlertTriggered`.
        case alertTriggered(message: String, recipients: [String], ruleId: String, sheetId: String)
        /// The event `AttachmentsChanged`.
        case attachmentsChanged(sheetId: String)
        /// The event `AxesChanged`.
        case axesChanged(count: UInt32, sheetId: String)
        /// The event `CellCleared`.
        case cellCleared(colId: String, rowId: String, sheetId: String)
        /// The event `CellUpdated`.
        case cellUpdated(id: String, sheetId: String)
        /// The event `CellsChanged`.
        case cellsChanged(count: UInt32, sheetId: String)
        /// The event `ChartsChanged`.
        case chartsChanged(sheetId: String)
        /// The event `CommentAdded`.
        case commentAdded(author: String, id: String, mentions: [String], sheetId: String)
        /// The event `CommentChanged`.
        case commentChanged(id: String, sheetId: String)
        /// The event `LinkedChanged`.
        case linkedChanged(sheetId: String)
        /// The event `MemberJoined`.
        case memberJoined(id: String, nickname: String)
        /// The event `MemberRenamed`.
        case memberRenamed(id: String, nickname: String)
        /// The event `NamedRangesChanged`.
        case namedRangesChanged(name: String)
        /// The event `NoteChanged`.
        case noteChanged(colId: String, rowId: String, sheetId: String)
        /// The event `ProjectInitialized`.
        case projectInitialized(id: String, name: String)
        /// The event `ProtectionsChanged`.
        case protectionsChanged(sheetId: String)
        /// The event `PublicationsChanged`.
        case publicationsChanged(sheetId: String)
        /// The event `RolesChanged`.
        case rolesChanged(memberId: String)
        /// The event `RulesChanged`.
        case rulesChanged(sheetId: String)
        /// The event `SheetCreated`.
        case sheetCreated(id: String, name: String)
        /// The event `SheetDeleted`.
        case sheetDeleted(id: String)
        /// The event `SheetRenamed`.
        case sheetRenamed(id: String, name: String)
        /// The event `SheetViewChanged`.
        case sheetViewChanged(sheetId: String)
        /// The event `StylesChanged`.
        case stylesChanged(sheetId: String)
        /// An event this client does not know: one a newer release of the app added.
        case unknown(kind: String, data: JSONValue?)

        /// An event's `kind` and `data`, typed; a known kind whose data does not fit throws.
        public init(kind: String, data: JSONValue?) throws {
            let fields = Fields(data)
            switch kind {
            case "AlertTriggered": self = try .alertTriggered(message: fields.decode("message", String.self), recipients: fields.decode("recipients", [String].self), ruleId: fields.decode("ruleId", String.self), sheetId: fields.decode("sheetId", String.self))
            case "AttachmentsChanged": self = try .attachmentsChanged(sheetId: fields.decode("sheetId", String.self))
            case "AxesChanged": self = try .axesChanged(count: fields.decode("count", UInt32.self), sheetId: fields.decode("sheetId", String.self))
            case "CellCleared": self = try .cellCleared(colId: fields.decode("colId", String.self), rowId: fields.decode("rowId", String.self), sheetId: fields.decode("sheetId", String.self))
            case "CellUpdated": self = try .cellUpdated(id: fields.decode("id", String.self), sheetId: fields.decode("sheetId", String.self))
            case "CellsChanged": self = try .cellsChanged(count: fields.decode("count", UInt32.self), sheetId: fields.decode("sheetId", String.self))
            case "ChartsChanged": self = try .chartsChanged(sheetId: fields.decode("sheetId", String.self))
            case "CommentAdded": self = try .commentAdded(author: fields.decode("author", String.self), id: fields.decode("id", String.self), mentions: fields.decode("mentions", [String].self), sheetId: fields.decode("sheetId", String.self))
            case "CommentChanged": self = try .commentChanged(id: fields.decode("id", String.self), sheetId: fields.decode("sheetId", String.self))
            case "LinkedChanged": self = try .linkedChanged(sheetId: fields.decode("sheetId", String.self))
            case "MemberJoined": self = try .memberJoined(id: fields.decode("id", String.self), nickname: fields.decode("nickname", String.self))
            case "MemberRenamed": self = try .memberRenamed(id: fields.decode("id", String.self), nickname: fields.decode("nickname", String.self))
            case "NamedRangesChanged": self = try .namedRangesChanged(name: fields.decode("name", String.self))
            case "NoteChanged": self = try .noteChanged(colId: fields.decode("colId", String.self), rowId: fields.decode("rowId", String.self), sheetId: fields.decode("sheetId", String.self))
            case "ProjectInitialized": self = try .projectInitialized(id: fields.decode("id", String.self), name: fields.decode("name", String.self))
            case "ProtectionsChanged": self = try .protectionsChanged(sheetId: fields.decode("sheetId", String.self))
            case "PublicationsChanged": self = try .publicationsChanged(sheetId: fields.decode("sheetId", String.self))
            case "RolesChanged": self = try .rolesChanged(memberId: fields.decode("memberId", String.self))
            case "RulesChanged": self = try .rulesChanged(sheetId: fields.decode("sheetId", String.self))
            case "SheetCreated": self = try .sheetCreated(id: fields.decode("id", String.self), name: fields.decode("name", String.self))
            case "SheetDeleted": self = try .sheetDeleted(id: fields.decode("id", String.self))
            case "SheetRenamed": self = try .sheetRenamed(id: fields.decode("id", String.self), name: fields.decode("name", String.self))
            case "SheetViewChanged": self = try .sheetViewChanged(sheetId: fields.decode("sheetId", String.self))
            case "StylesChanged": self = try .stylesChanged(sheetId: fields.decode("sheetId", String.self))
            default: self = .unknown(kind: kind, data: data)
            }
        }
    }

    /// One frame of `events`: the event's log position (`index:seq`) and the event.
    public struct EventFrame: Sendable {
        public let id: String
        public let event: Event
    }

    /// The app's refusal: a `422 APP_ERROR`'s code and fields (`AppError.appCode`, `fields`), typed.
    public enum Refusal: Sendable {
        /// The error `Forbidden`.
        case forbidden(message: String)
        /// The error `Invalid`.
        case invalid(message: String)
        /// The error `NotFound`.
        case notFound(message: String)
        /// A code this client does not know, or fields that do not fit it.
        case unknown(code: String, fields: [String: JSONValue])

        /// `error`'s code and fields, typed.
        public init(_ error: MeroKit.AppError) {
            self = (try? Self.decode(error)) ?? .unknown(code: error.appCode, fields: error.fields)
        }

        private static func decode(_ error: MeroKit.AppError) throws -> Self {
            let fields = Fields(.object(error.fields))
            switch error.appCode {
            case "Forbidden": return try .forbidden(message: fields.decode("message", String.self))
            case "Invalid": return try .invalid(message: fields.decode("message", String.self))
            case "NotFound": return try .notFound(message: fields.decode("message", String.self))
            default: return .unknown(code: error.appCode, fields: error.fields)
            }
        }
    }

    /// A `u64` or `i64` as the wire carries it: a decimal string (a number is read too).
    public struct DecimalString<Integer: FixedWidthInteger & Codable & Sendable>: Codable, Sendable, Hashable {
        public var value: Integer

        public init(_ value: Integer) {
            self.value = value
        }

        public init(from decoder: Decoder) throws {
            let container = try decoder.singleValueContainer()
            if let text = try? container.decode(String.self) {
                guard let value = Integer(text) else {
                    throw DecodingError.dataCorruptedError(in: container, debugDescription: "not a decimal integer: \(text)")
                }
                self.value = value
            } else {
                value = try container.decode(Integer.self)
            }
        }

        public func encode(to encoder: Encoder) throws {
            var container = encoder.singleValueContainer()
            try container.encode(String(value))
        }
    }

    /// `bytes` as the wire carries them: base64url without padding (padding is read too).
    public struct Base64URL: Codable, Sendable, Hashable {
        public var data: Data

        public init(_ data: Data) {
            self.data = data
        }

        public init(from decoder: Decoder) throws {
            let container = try decoder.singleValueContainer()
            let text = try container.decode(String.self)
            var base64 = text.replacingOccurrences(of: "-", with: "+").replacingOccurrences(of: "_", with: "/")
            base64 = base64.trimmingCharacters(in: CharacterSet(charactersIn: "="))
            base64 += String(repeating: "=", count: (4 - base64.count % 4) % 4)
            guard let data = Data(base64Encoded: base64) else {
                throw DecodingError.dataCorruptedError(in: container, debugDescription: "not base64url: \(text)")
            }
            self.data = data
        }

        public func encode(to encoder: Encoder) throws {
            var container = encoder.singleValueContainer()
            let text = data.base64EncodedString()
                .replacingOccurrences(of: "+", with: "-")
                .replacingOccurrences(of: "/", with: "_")
                .trimmingCharacters(in: CharacterSet(charactersIn: "="))
            try container.encode(text)
        }
    }

    /// A method's arguments by name; a `nil` option is sent as `null`.
    fileprivate struct Args: Encodable {
        var entries: [(String, any Encodable)] = []

        mutating func add(_ name: String, _ value: some Encodable) {
            entries.append((name, value))
        }

        func encode(to encoder: Encoder) throws {
            var container = encoder.container(keyedBy: Key.self)
            for (name, value) in entries {
                try container.encode(value, forKey: Key(name))
            }
        }
    }

    fileprivate struct Key: CodingKey {
        var stringValue: String
        var intValue: Int? { nil }

        init(_ name: String) {
            stringValue = name
        }

        init?(stringValue: String) {
            self.stringValue = stringValue
        }

        init?(intValue: Int) {
            return nil
        }
    }

    /// The `result` of a call's or view's answer; a missing one reads as `null`.
    fileprivate struct Answer<Wire: Decodable>: Decodable {
        let result: Wire

        private enum CodingKeys: String, CodingKey {
            case result
        }

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            if container.contains(.result) {
                result = try container.decode(Wire.self, forKey: .result)
            } else {
                result = try JSONDecoder().decode(Wire.self, from: Data("null".utf8))
            }
        }
    }

    /// An event's or error's fields; a missing one reads as `null`.
    fileprivate struct Fields {
        let object: [String: JSONValue]

        init(_ data: JSONValue?) {
            if case .object(let object)? = data {
                self.object = object
            } else {
                object = [:]
            }
        }

        func decode<Wire: Decodable>(_ name: String, _ type: Wire.Type) throws -> Wire {
            try JSONDecoder().decode(Wire.self, from: JSONEncoder().encode(object[name] ?? .null))
        }
    }

    private static func json(_ args: Args) throws -> Data {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
        return try encoder.encode(args)
    }

    private static func result<Wire: Decodable>(_ type: Wire.Type, of answer: Data) throws -> Wire {
        try JSONDecoder().decode(Answer<Wire>.self, from: answer).result
    }
}
